<?php
declare(strict_types=1);
require __DIR__.'/db.php';require __DIR__.'/helpers.php';admin_required();
$tab=(string)($_GET['tab']??'paid');$q=trim((string)($_GET['q']??''));$where=match($tab){'pending'=>"o.status='Paid / Pending Delivery'",'shipped'=>"o.status='Shipped'",'unpaid'=>"o.status='Pending Payment'",default=>"o.status IN ('Paid / Pending Delivery','Shipped')"};$args=[];if($q!==''){$where.=' AND (CAST(o.order_number AS CHAR) LIKE ? OR o.customer_name LIKE ? OR o.phone LIKE ?)';$like='%'.$q.'%';$args=[$like,$like,$like];}$s=$pdo->prepare("SELECT o.* FROM orders o WHERE $where ORDER BY o.created_at DESC LIMIT 500");$s->execute($args);$orders=[];foreach($s as $o){$i=$pdo->prepare('SELECT product_name,size,qty,unit_price FROM order_items WHERE order_id=?');$i->execute([$o['id']]);$phone=preg_replace('/\D/','',$o['phone']);if(str_starts_with($phone,'0'))$phone='234'.substr($phone,1);elseif(str_starts_with($phone,'234')){}elseif(str_starts_with($phone,'+234'))$phone=substr($phone,1);$orders[]=['id'=>(int)$o['id'],'order_number'=>(int)$o['order_number'],'created_at_label'=>date('M j, Y, h:i A',strtotime($o['created_at'])),'customer_name'=>$o['customer_name'],'phone'=>$o['phone'],'whatsapp_phone'=>$phone,'email'=>$o['email'],'address'=>$o['address'],'state'=>$o['state'],'subtotal'=>(float)$o['subtotal'],'delivery_fee'=>(float)$o['delivery_fee'],'total'=>(float)$o['total'],'status'=>$o['status'],'items'=>$i->fetchAll()];}json_out(['orders'=>$orders]);
